-- =====================================================================
-- PSP customer KYC tiers, e-money wallets, agent network, ZiG/USD FX
-- GENERATED by tools/codegen/gen_ddl.py from accounts.spec
-- (same specs as the JPA entities). Edit the spec, regenerate, never hand-edit.
-- =====================================================================

-- A wallet customer and their KYC tier. National ID encrypted, with a blind index for duplicate detection.
CREATE TABLE psp_customer_profiles (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    customer_ref                 VARCHAR(40) NOT NULL,
    msisdn                       VARCHAR(20) NOT NULL,
    user_id                      BIGINT,
    first_name                   VARCHAR(100),
    last_name                    VARCHAR(100),
    date_of_birth                DATE,
    national_id                  VARCHAR(600),
    national_id_index            VARCHAR(64),
    kyc_tier                     VARCHAR(10) NOT NULL,
    id_verification_result       VARCHAR(20),
    id_verification_ref          VARCHAR(120),
    id_verified_at               DATETIME(6),
    proof_of_residence_ref       VARCHAR(200),
    pep                          BOOLEAN NOT NULL DEFAULT FALSE,
    sanctions_status             VARCHAR(20) NOT NULL,
    risk_rating                  VARCHAR(10) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    status_reason                VARCHAR(500),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_customer_profiles_customer_ref UNIQUE (customer_ref),
    CONSTRAINT uq_customer_profiles_msisdn UNIQUE (msisdn),
    CONSTRAINT uq_customer_profiles_national_id_index UNIQUE (national_id_index),
    INDEX idx_cust_tier (kyc_tier)
);

-- Wallet limits per KYC tier and currency. Set these to your RBZ licence conditions.
CREATE TABLE psp_kyc_tier_limits (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    kyc_tier                     VARCHAR(10) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    max_balance_minor            BIGINT NOT NULL DEFAULT 0,
    max_txn_minor                BIGINT NOT NULL DEFAULT 0,
    daily_debit_minor            BIGINT NOT NULL DEFAULT 0,
    monthly_debit_minor          BIGINT NOT NULL DEFAULT 0,
    daily_count                  INT NOT NULL DEFAULT 0,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_tier_ccy UNIQUE (kyc_tier,currency)
);

-- An e-money wallet. The balance is NOT stored here: it is the CUSTOMER_WALLET (or AGENT_FLOAT) ledger account.
CREATE TABLE psp_wallets (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    wallet_ref                   VARCHAR(40) NOT NULL,
    owner_type                   VARCHAR(20) NOT NULL,
    owner_ref                    VARCHAR(60) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    pin_hash                     VARCHAR(200),
    pin_failures                 INT NOT NULL DEFAULT 0,
    locked_until                 DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_wallets_wallet_ref UNIQUE (wallet_ref),
    CONSTRAINT uq_wallet_owner UNIQUE (owner_type,owner_ref,currency)
);

-- Business record of a wallet operation. The money movement itself is the ledger entry in journalEntryRef.
CREATE TABLE psp_wallet_transfers (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    transfer_ref                 VARCHAR(40) NOT NULL,
    type                         VARCHAR(30) NOT NULL,
    channel                      VARCHAR(20) NOT NULL,
    from_ref                     VARCHAR(60),
    to_ref                       VARCHAR(60),
    merchant_id                  BIGINT,
    agent_id                     BIGINT,
    currency                     VARCHAR(3) NOT NULL,
    amount_minor                 BIGINT NOT NULL DEFAULT 0,
    fee_minor                    BIGINT NOT NULL DEFAULT 0,
    tax_minor                    BIGINT NOT NULL DEFAULT 0,
    commission_minor             BIGINT NOT NULL DEFAULT 0,
    status                       VARCHAR(20) NOT NULL,
    risk_decision                VARCHAR(20),
    journal_entry_ref            VARCHAR(40),
    external_ref                 VARCHAR(150),
    narrative                    VARCHAR(200),
    initiated_by                 VARCHAR(120) NOT NULL,
    failure_reason               VARCHAR(500),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_wallet_transfers_transfer_ref UNIQUE (transfer_ref),
    INDEX idx_wt_from (from_ref,created_at),
    INDEX idx_wt_to (to_ref,created_at),
    INDEX idx_wt_type (type,created_at)
);

-- Banded customer fees and agent commissions per operation (P2P, CASH_OUT, CASH_IN, WITHDRAWAL). Tiered bands are typical for Zimbabwean mobile money.
CREATE TABLE psp_wallet_tariffs (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    operation                    VARCHAR(20) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    band_min_minor               BIGINT NOT NULL DEFAULT 0,
    band_max_minor               BIGINT NOT NULL DEFAULT 0,
    customer_fee_fixed_minor     BIGINT NOT NULL DEFAULT 0,
    customer_fee_bps             INT NOT NULL DEFAULT 0,
    agent_commission_fixed_minor BIGINT NOT NULL DEFAULT 0,
    agent_commission_bps         INT NOT NULL DEFAULT 0,
    status                       VARCHAR(20) NOT NULL,
    approved_by                  VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    INDEX idx_tariff_lookup (operation,currency,status)
);

-- A cash-in / cash-out agent (or super-agent managing a network of agents).
CREATE TABLE psp_agents (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    agent_ref                    VARCHAR(40) NOT NULL,
    agent_code                   VARCHAR(10) NOT NULL,
    agent_type                   VARCHAR(20) NOT NULL,
    parent_agent_id              BIGINT,
    business_name                VARCHAR(200) NOT NULL,
    contact_name                 VARCHAR(200),
    msisdn                       VARCHAR(20) NOT NULL,
    national_id_index            VARCHAR(64),
    province                     VARCHAR(60),
    district                     VARCHAR(60),
    gps_lat                      VARCHAR(20),
    gps_lng                      VARCHAR(20),
    status                       VARCHAR(20) NOT NULL,
    kyc_verified                 BOOLEAN NOT NULL DEFAULT FALSE,
    risk_rating                  VARCHAR(10) NOT NULL,
    per_txn_limit_minor          BIGINT NOT NULL DEFAULT 0,
    daily_cash_in_limit_minor    BIGINT NOT NULL DEFAULT 0,
    daily_cash_out_limit_minor   BIGINT NOT NULL DEFAULT 0,
    max_float_minor              BIGINT NOT NULL DEFAULT 0,
    pin_hash                     VARCHAR(200),
    pin_failures                 INT NOT NULL DEFAULT 0,
    locked_until                 DATETIME(6),
    status_reason                VARCHAR(500),
    created_by                   VARCHAR(120) NOT NULL,
    approved_by                  VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_agents_agent_ref UNIQUE (agent_ref),
    CONSTRAINT uq_agents_agent_code UNIQUE (agent_code),
    CONSTRAINT uq_agents_msisdn UNIQUE (msisdn),
    INDEX idx_agent_parent (parent_agent_id),
    INDEX idx_agent_status (status)
);

-- An FX rate snapshot (RBZ interbank or treasury-entered). Manual rates need four-eyes approval.
CREATE TABLE psp_fx_rates (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    rate_ref                     VARCHAR(40) NOT NULL,
    base_ccy                     VARCHAR(3) NOT NULL,
    quote_ccy                    VARCHAR(3) NOT NULL,
    bid                          DECIMAL(18,8) NOT NULL,
    ask                          DECIMAL(18,8) NOT NULL,
    mid                          DECIMAL(18,8) NOT NULL,
    as_of                        DATETIME(6) NOT NULL,
    source                       VARCHAR(20) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    created_by                   VARCHAR(120) NOT NULL,
    approved_by                  VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_fx_rates_rate_ref UNIQUE (rate_ref),
    INDEX idx_fx_pair (base_ccy,quote_ccy,status,as_of)
);

-- A customer currency conversion with the exact rate and spread applied.
CREATE TABLE psp_fx_conversions (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    conversion_ref               VARCHAR(40) NOT NULL,
    customer_ref                 VARCHAR(60) NOT NULL,
    from_ccy                     VARCHAR(3) NOT NULL,
    to_ccy                       VARCHAR(3) NOT NULL,
    from_amount_minor            BIGINT NOT NULL DEFAULT 0,
    to_amount_minor              BIGINT NOT NULL DEFAULT 0,
    mid_amount_minor             BIGINT NOT NULL DEFAULT 0,
    customer_rate                DECIMAL(18,8) NOT NULL,
    mid_rate                     DECIMAL(18,8) NOT NULL,
    rate_ref                     VARCHAR(40) NOT NULL,
    sell_entry_ref               VARCHAR(40),
    buy_entry_ref                VARCHAR(40),
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_fx_conversions_conversion_ref UNIQUE (conversion_ref),
    INDEX idx_fxc_customer (customer_ref,created_at)
);
